  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: "Segoe UI", system-ui, -apple-system, Arial, sans-serif;
    background: linear-gradient(160deg, #eef1ff 0%, var(--bg) 45%);
    color: var(--text);
