  .todo-item.completed .todo-text {
    text-decoration: line-through;
    color: var(--done);
  }

  .delete-btn {
    flex-shrink: 0;
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.1rem;
    line-height: 1;
    color: var(--muted);
    background: transparent;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.15s;
  }

  .delete-btn:hover {
    color: #fff;
    background: var(--danger);
  }

  /* ---- Footer / empty state ---- */
  .empty-state {
    padding: 36px 16px;
    text-align: center;
    color: var(--muted);
    font-size: 0.95rem;
  }

  .stats {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    font-size: 0.85rem;
    color: var(--muted);
    background: #fafbff;
