  }

  #clear-completed {
    background: none;
    border: none;
    color: var(--muted);
    font-size: 0.85rem;
    cursor: pointer;
    transition: color 0.15s;
  }

  #clear-completed:hover { color: var(--danger); }
  #clear-completed:disabled { opacity: 0.4; cursor: default; }
</style>
</head>
<body>
  <main class="app">
    <h1>Todos</h1>
    <p class="subtitle">Stay organized. Your list is saved automatically.</p>

    <section class="card">
      <form id="todo-form" class="input-row">
        <input
          type="text"
          id="todo-input"
          placeholder="What needs to be done?"
          autocomplete="off"
          maxlength="300"
          aria-label="New todo"
        >
        <button type="submit" id="add-btn">Add</button>
      </form>

      <nav class="filters" aria-label="Filter todos">
        <button class="filter-btn active" data-filter="all">All</button>
        <button class="filter-btn" data-filter="active">Active</button>
        <button class="filter-btn" data-filter="completed">Completed</button>
      </nav>

      <ul id="todo-list" aria-live="polite"></ul>

      <div class="stats">
        <span id="items-left">0 items left</span>
        <button id="clear-completed" type="button">Clear completed</button>
      </div>
    </section>
  </main>

<script>
(function () {
  'use strict';

  var STORAGE_KEY = 'todos.ollama-qwen3.8-flash-next-125b-a6b-q4_01';

  /** @type {{id:string,text:string,completed:boolean}[]} */
  var todos = loadTodos();
  var currentFilter = 'all';

  var form = document.getElementById('todo-form');
  var input = document.getElementById('todo-input');
  var listEl = document.getElementById('todo-list');
  var itemsLeftEl = document.getElementById('items-left');
  var clearBtn = document.getElementById('clear-completed');
  var filterBtns = Array.prototype.slice.call(document.querySelectorAll('.filter-btn'));

  // ---------- Persistence ----------

  function loadTodos() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(function (t) {
        return t && typeof t.text === 'string';
      }).map(function (t) {
        return {
          id: typeof t.id === 'string' ? t.id : makeId(),
          text: t.text,
          completed: !!t.completed
        };
      });
    } catch (e) {
      return [];
    }
  }

  function saveTodos() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (e) {
      // Storage full or unavailable — app keeps working in-memory.
    }
  }

  function makeId() {
    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 9);
  }

  // ---------- Actions ----------

  function addTodo(text) {
    todos.push({ id: makeId(), text: text, completed: false });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    todos.forEach(function (t) {
      if (t.id === id) t.completed = !t.completed;
    });
    saveTodos();
    render();
  }

  function deleteTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    saveTodos();
    render();
  }

  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  }

  function setFilter(filter) {
    currentFilter = filter;
    filterBtns.forEach(function (btn) {
      btn.classList.toggle('active', btn.dataset.filter === filter);
    });
    render();
  }

  // ---------- Rendering ----------

  function visibleTodos() {
    if (currentFilter === 'active') {
      return todos.filter(function (t) { return !t.completed; });
    }
    if (currentFilter === 'completed') {
      return todos.filter(function (t) { return t.completed; });
    }
    return todos;
  }

  function render() {
    listEl.innerHTML = '';
    var items = visibleTodos();

    if (items.length === 0) {
      var empty = document.createElement('li');
      empty.className = 'empty-state';
      empty.textContent =
        todos.length === 0
          ? 'No todos yet. Add one above!'
          : currentFilter === 'active'
            ? 'Nothing active — nice work!'
            : 'No completed todos yet.';
      listEl.appendChild(empty);
    } else {
      items.forEach(function (todo) {
        listEl.appendChild(createTodoElement(todo));
      });
    }

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    itemsLeftEl.textContent = activeCount + (activeCount === 1 ? ' item left' : ' items left');

    var completedCount = todos.length - activeCount;
    clearBtn.disabled = completedCount === 0;
  }

  function createTodoElement(todo) {
    var li = document.createElement('li');
    li.className = 'todo-item' + (todo.completed ? ' completed' : '');
    li.dataset.id = todo.id;

    var checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.className = 'todo-checkbox';
    checkbox.checked = todo.completed;
    checkbox.setAttribute('aria-label',
      (todo.completed ? 'Mark active: ' : 'Mark complete: ') + todo.text);
    checkbox.addEventListener('change', function () {
      toggleTodo(todo.id);
    });

    var span = document.createElement('span');
    span.className = 'todo-text';
    span.textContent = todo.text;
    span.addEventListener('click', function () {
      toggleTodo(todo.id);
    });

    var delBtn = document.createElement('button');
    delBtn.type = 'button';
    delBtn.className = 'delete-btn';
    delBtn.textContent = '\u00D7';
    delBtn.setAttribute('aria-label', 'Delete: ' + todo.text);
    delBtn.addEventListener('click', function () {
      deleteTodo(todo.id);
    });

    li.appendChild(checkbox);
    li.appendChild(span);
    li.appendChild(delBtn);
    return li;
  }

  // ---------- Events ----------

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var text = input.value.trim();
    if (!text) return;
    addTodo(text);
    input.value = '';
    input.focus();
  });

  filterBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      setFilter(btn.dataset.filter);
    });
  });

  clearBtn.addEventListener('click', clearCompleted);

  // Initial paint
  render();
})();
</script>
</body>
</html>
